using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Text;using System.Security.Cryptography;using System.Web.Script.Serialization;
public static class UpdateTests {
 static List<string> log=new List<string>();static void Check(bool ok,string name){if(!ok)throw new Exception(name);log.Add("PASS "+name);}
 sealed class Endpoint : IDisposable {
  readonly System.Net.Sockets.TcpListener listener;readonly System.Threading.Tasks.Task worker;public string Url;
  public Endpoint(byte[] response){listener=new System.Net.Sockets.TcpListener(System.Net.IPAddress.Loopback,0);listener.Start();Url="http://127.0.0.1:"+((System.Net.IPEndPoint)listener.LocalEndpoint).Port+"/setup.exe";worker=System.Threading.Tasks.Task.Run(()=>{using(var client=listener.AcceptTcpClient())using(var stream=client.GetStream()){client.ReceiveTimeout=5000;var reader=new StreamReader(stream,Encoding.ASCII,false,1024,true);while(!string.IsNullOrEmpty(reader.ReadLine())){}var header=Encoding.ASCII.GetBytes("HTTP/1.1 200 OK\r\nContent-Type: application/octet-stream\r\nContent-Length: "+response.Length+"\r\nConnection: close\r\n\r\n");stream.Write(header,0,header.Length);stream.Write(response,0,response.Length);}});}
  public void Dispose(){listener.Stop();try{worker.Wait(5000);}catch{}}
 }
 static byte[] Signed(ReleaseInfo release,RSACryptoServiceProvider rsa){var json=new JavaScriptSerializer();var payload=Encoding.UTF8.GetBytes(json.Serialize(release));return Encoding.UTF8.GetBytes(json.Serialize(new ReleaseEnvelope{payload=Convert.ToBase64String(payload),signature=Convert.ToBase64String(rsa.SignData(payload,CryptoConfig.MapNameToOID("SHA256")))}));}
 static void Reject(Action test,string name){try{test();}catch(InvalidDataException){log.Add("PASS "+name);return;}throw new Exception("not rejected: "+name);}
 public static int Run(string folder){Directory.CreateDirectory(folder);try{
  using(var rsa=new RSACryptoServiceProvider(2048)){rsa.PersistKeyInCsp=false;var release=new ReleaseInfo{appId="AQServer",version="12.5.0",publishedUtc="2026-10-22T00:00:00Z",notes="测试更新",installerUrl="http://8.140.49.4/aqserver/releases/setup.exe",installerBytes=2048,installerSha256=new string('A',64)};string key=rsa.ToXmlString(false);var bytes=Signed(release,rsa);var verified=AppUpdates.VerifyManifest(bytes,key);Check(verified.ParsedVersion>AppUpdates.CurrentVersion&&verified.notes==release.notes,"signed release and UTF-8 notes accepted");
   var envelope=new JavaScriptSerializer().Deserialize<ReleaseEnvelope>(Encoding.UTF8.GetString(bytes));var payload=Convert.FromBase64String(envelope.payload);payload[payload.Length/2]^=1;envelope.payload=Convert.ToBase64String(payload);Reject(()=>AppUpdates.VerifyManifest(Encoding.UTF8.GetBytes(new JavaScriptSerializer().Serialize(envelope)),key),"tampered manifest rejected");
   using(var wrong=new RSACryptoServiceProvider(2048)){wrong.PersistKeyInCsp=false;Reject(()=>AppUpdates.VerifyManifest(bytes,wrong.ToXmlString(false)),"wrong signing key rejected");}
   Reject(()=>AppUpdates.VerifyManifest(new byte[65537],key),"oversized manifest rejected");Reject(()=>AppUpdates.VerifyManifest(Encoding.UTF8.GetBytes("{}"),key),"missing signature rejected");
   release.appId="OtherApp";Reject(()=>AppUpdates.VerifyManifest(Signed(release,rsa),key),"wrong product rejected");release.appId="AQServer";release.installerUrl="file:///C:/unsafe.exe";Reject(()=>AppUpdates.VerifyManifest(Signed(release,rsa),key),"non-web installer URL rejected");release.installerUrl="http://8.140.49.4/aqserver/setup.exe";release.installerBytes=long.MaxValue;Reject(()=>AppUpdates.VerifyManifest(Signed(release,rsa),key),"oversized installer rejected");release.installerBytes=2048;
   string path=Path.Combine(folder,"installer-fixture.bin");File.WriteAllBytes(path,Enumerable.Range(0,2048).Select(i=>(byte)i).ToArray());using(var sha=SHA256.Create())release.installerSha256=BitConverter.ToString(sha.ComputeHash(File.ReadAllBytes(path))).Replace("-","");AppUpdates.VerifyInstaller(path,release);Check(true,"exact installer length and SHA256 accepted");var changed=File.ReadAllBytes(path);changed[300]^=1;File.WriteAllBytes(path,changed);Reject(()=>AppUpdates.VerifyInstaller(path,release),"modified installer rejected");File.WriteAllBytes(path,new byte[10]);Reject(()=>AppUpdates.VerifyInstaller(path,release),"truncated installer rejected");File.Delete(path);
   var fixture=Enumerable.Range(0,2048).Select(i=>(byte)i).ToArray();using(var sha=SHA256.Create())release.installerSha256=BitConverter.ToString(sha.ComputeHash(fixture)).Replace("-","");
   using(var http=new Endpoint(fixture)){release.installerUrl=http.Url;var downloaded=AppUpdates.DownloadTo(release,null,System.Threading.CancellationToken.None,folder).GetAwaiter().GetResult();Check(File.ReadAllBytes(downloaded).SequenceEqual(fixture),"HTTP download streams and validates exact bytes");File.Delete(downloaded);}
   using(var http=new Endpoint(Signed(release,rsa))){var info=AppUpdates.CheckAt(http.Url,key,System.Threading.CancellationToken.None).GetAwaiter().GetResult();Check(info.version==release.version,"HTTP manifest request verifies signature before use");}
   using(var cancelled=new System.Threading.CancellationTokenSource()){cancelled.Cancel();try{AppUpdates.DownloadTo(release,null,cancelled.Token,folder).GetAwaiter().GetResult();throw new Exception("cancel failed");}catch(OperationCanceledException){Check(true,"cancelled download does not start");}}

  }
  string manifest=Environment.GetEnvironmentVariable("AQSERVER_RELEASE_MANIFEST");if(!string.IsNullOrEmpty(manifest)){var release=AppUpdates.VerifyManifest(File.ReadAllBytes(manifest),UpdatePublicKey.Xml);Check(release.ParsedVersion==AppUpdates.CurrentVersion,"published manifest matches embedded public key and application version");string installer=Environment.GetEnvironmentVariable("AQSERVER_RELEASE_INSTALLER");if(!string.IsNullOrEmpty(installer)){AppUpdates.VerifyInstaller(installer,release);Check(true,"published installer matches signed release");}}
  File.WriteAllLines(Path.Combine(folder,"update-results.txt"),log);return 0;
 }catch(Exception ex){File.WriteAllLines(Path.Combine(folder,"update-results.txt"),log);File.WriteAllText(Path.Combine(folder,"update-error.txt"),ex.ToString());return 1;}}
}
